// server/tools/browser.js
var MAX_NAV_TIMEOUT = 3e4;
var MAX_SCREENSHOT_W = 1920;
var MAX_SCREENSHOT_H = 1080;
var BLOCKED_HOSTS = [
  "localhost",
  "127.0.0.1",
  "0.0.0.0",
  "::1",
  "[::1]"
];
var ALLOWED_HOSTS = [];
function isHostBlocked(hostname) {
  const h = hostname.toLowerCase();
  if (BLOCKED_HOSTS.some((b) => h === b || h.endsWith(`.${b}`))) return true;
  if (ALLOWED_HOSTS.length > 0 && !ALLOWED_HOSTS.some((a) => h === a || h.endsWith(`.${a}`))) return true;
  return false;
}
function validateUrl(raw) {
  let url;
  try {
    url = new URL(raw);
  } catch {
    throw new Error(`Invalid URL: "${raw}"`);
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") throw new Error(`Only http/https allowed, got: ${url.protocol}`);
  if (isHostBlocked(url.hostname)) throw new Error(`URL host is blocked: ${url.hostname}`);
  return url;
}
var browser = null;
var page = null;
async function ensureBrowser() {
  if (!browser) {
    const puppeteer = await import("puppeteer").then((m) => m.default || m);
    browser = await puppeteer.launch({
      headless: true,
      args: ["--no-sandbox", "--disable-setuid-sandbox"]
    });
  }
  if (!page) {
    page = await browser.newPage();
    await page.setViewport({ width: 1280, height: 720 });
    await page.setRequestInterception(true);
    page.on("request", (req) => {
      const resourceType = req.resourceType();
      if (resourceType === "document" && req.url().match(/\.(pdf|zip|exe|dmg|pkg|deb|rpm|tar\.gz|tgz|bz2|7z|jar|war|apk|ipa)$/i)) {
        req.abort("blockedbyclient");
        return;
      }
      if (["media", "font"].includes(resourceType)) {
        req.abort("blockedbyclient");
        return;
      }
      req.continue();
    });
  }
  return { browser, page };
}
async function actionNavigate({ url }) {
  const validated = validateUrl(url);
  const { page: page2 } = await ensureBrowser();
  await page2.goto(validated.href, { waitUntil: "networkidle2", timeout: MAX_NAV_TIMEOUT });
  const title = await page2.title().catch(() => "");
  const finalUrl = page2.url();
  return { action: "navigate", url: finalUrl, title };
}
async function actionClick({ selector }) {
  if (!selector?.trim()) throw new Error('click requires "selector"');
  const { page: page2 } = await ensureBrowser();
  await page2.waitForSelector(selector, { timeout: 1e4 });
  await page2.click(selector);
  await new Promise((r) => setTimeout(r, 500));
  return { action: "click", selector, clicked: true };
}
async function actionType({ selector, text }) {
  if (!selector?.trim()) throw new Error('type requires "selector"');
  if (typeof text !== "string") throw new Error('type requires "text"');
  const { page: page2 } = await ensureBrowser();
  await page2.waitForSelector(selector, { timeout: 1e4 });
  await page2.focus(selector);
  await page2.keyboard.type(text, { delay: 10 });
  return { action: "type", selector, typed: text.length };
}
async function actionExtract({ selector }) {
  const { page: page2 } = await ensureBrowser();
  if (selector?.trim()) {
    const el = await page2.$(selector);
    if (!el) return { action: "extract", selector, text: "", found: false };
    const text2 = await page2.evaluate((e) => e.innerText || e.textContent || "", el);
    return { action: "extract", selector, text: String(text2).slice(0, 5e3), found: true };
  }
  const text = await page2.evaluate(() => document.body.innerText || "");
  return { action: "extract", text: String(text).slice(0, 5e3), found: true };
}
async function actionScreenshot({ selector }) {
  const { page: page2 } = await ensureBrowser();
  let clip = null;
  if (selector?.trim()) {
    const el = await page2.$(selector);
    if (!el) throw new Error(`Element not found for screenshot: ${selector}`);
    const box = await el.boundingBox();
    if (!box) throw new Error(`Element has no bounding box: ${selector}`);
    clip = {
      x: box.x,
      y: box.y,
      width: Math.min(Math.round(box.width), MAX_SCREENSHOT_W),
      height: Math.min(Math.round(box.height), MAX_SCREENSHOT_H)
    };
  } else {
    const viewport = await page2.viewport();
    clip = { x: 0, y: 0, width: Math.min(viewport.width, MAX_SCREENSHOT_W), height: Math.min(viewport.height, MAX_SCREENSHOT_H) };
  }
  const buf = await page2.screenshot({ clip, encoding: "base64", type: "png" });
  return { action: "screenshot", format: "png", base64: buf, width: clip.width, height: clip.height };
}
var ACTIONS = {
  navigate: actionNavigate,
  click: actionClick,
  type: actionType,
  extract: actionExtract,
  screenshot: actionScreenshot
};
async function runBrowserAction(action, args = {}) {
  const fn = ACTIONS[action];
  if (!fn) throw new Error(`Unknown browser action "${action}". Supported: ${Object.keys(ACTIONS).join(", ")}`);
  return fn(args);
}

// server/agentFive.js
var ReplyStreamer = class {
  constructor(onToken) {
    this.onToken = onToken;
    this.buf = "";
    this.state = "scanning";
    this.escape = false;
  }
  feed(rawChunk) {
    for (let i = 0; i < rawChunk.length; i++) {
      const ch = rawChunk[i];
      if (this.state === "scanning") {
        this.buf += ch;
        if (this.buf.length > 32) this.buf = this.buf.slice(-32);
        if (/"reply"\s*:\s*"$/.test(this.buf)) {
          this.state = "in_reply";
          this.buf = "";
          this.escape = false;
        }
      } else if (this.state === "in_reply") {
        if (this.escape) {
          this.escape = false;
          if (ch === "n") this.onToken("\n");
          else if (ch === "t") this.onToken("	");
          else if (ch === "r") this.onToken("\r");
          else if (ch === '"') this.onToken('"');
          else if (ch === "\\") this.onToken("\\");
          else if (ch === "/") this.onToken("/");
          else if (ch === "b") this.onToken("\b");
          else if (ch === "f") this.onToken("\f");
          else this.onToken(ch);
        } else if (ch === "\\") {
          this.escape = true;
        } else if (ch === '"') {
          this.state = "done";
        } else {
          this.onToken(ch);
        }
      }
    }
  }
};
